import {buildSupportPlan,sourceCard,salonFacts,SUPPORT_REVISION} from './support-core.js';
export function createSupportUI({state,config,esc,icon,toast,renderApp,startBooking}){
 const KEY='mimiroom-support-threads-v1';const s={open:false,busy:false,available:false,configured:false,checked:false,selected:null,outdated:false};
 const read=()=>{try{return JSON.parse(localStorage.getItem(KEY))||[]}catch{return[]}};
 const save=threads=>localStorage.setItem(KEY,JSON.stringify(threads));
 function thread(){let threads=read();let t=threads.find(t=>t.owner===state.userId);if(!t){t={id:crypto.randomUUID(),owner:state.userId,created:new Date().toISOString(),messages:[],mode:'auto',status:'open'};threads.push(t);save(threads)}return t}
 function append(role,text,extra={}){const current=thread();let threads=read(),t=threads.find(t=>t.id===current.id);t.messages.push({id:crypto.randomUUID(),role,text,at:new Date().toISOString(),...extra});t.messages=t.messages.slice(-100);t.updated=new Date().toISOString();save(threads);return t}
 function mount(){let root=document.querySelector('#support-root');if(!root){root=document.createElement('div');root.id='support-root';document.body.append(root)}if(state.portal!=='client'){root.innerHTML='';return}draw();if(!s.checked&&location.protocol!=='file:'){s.checked=true;fetch('/api/support/status',{signal:AbortSignal.timeout(2500)}).then(r=>r.ok?r.json():null).then(r=>{if(r?.mode){s.outdated=Boolean(r.configured)&&r.revision!==SUPPORT_REVISION;s.available=!s.outdated;s.configured=Boolean(r.configured)&&!s.outdated;if(state.portal==='client')draw()}}).catch(()=>{})}}
 function draw(){const root=document.querySelector('#support-root');if(!root)return;const t=thread();root.innerHTML=`<button class="support-launcher" id="support-toggle" aria-expanded="${s.open}" aria-label="${s.open?'Закрыть':'Открыть'} поддержку">${s.open?'×':icon('heart')}<span>${s.open?'Закрыть':'Поможем с уходом'}</span></button>${s.open?`<section class="support-chat" role="dialog" aria-label="Помощник МиМиРум"><header><div class="support-avatar">✳</div><div><h2>МиМиРум · на связи</h2><p>${t.mode==='human'?'Диалог с администратором · демо':s.configured?'ИИ-помощник · Groq':'Справочный режим · без нейросети'}</p></div><button id="support-close" aria-label="Закрыть поддержку">×</button></header><div class="support-intro">${s.outdated?'Обновление помощника готово. Перезапустите локальный сервер поддержки, чтобы включить новую версию ИИ. ' : ''}Цены — из прайса сайта. Итоговую стоимость и запись подтверждает студия. Не отправляйте в чат пароли и платёжные данные.</div><div class="support-messages" id="support-messages"><div class="support-message assistant"><p>Здравствуйте! Помогу выбрать уход и разобраться в ценах. Какая порода и вес у вашего питомца?</p><small>Помощник МиМиРум</small></div>${t.messages.map(m=>`<div class="support-message ${m.role==='user'?'user':m.role==='staff'?'staff':'assistant'}"><p>${esc(m.text)}</p>${m.sources?.length?`<div class="support-sources">${m.sources.map(c=>`<details><summary>${esc(c.title)} · ${esc(c.priceLabel)}</summary><p>${esc(c.description)}</p><a href="${salonFacts.website}/#services" target="_blank" rel="noopener">Прайс студии ↗</a></details>`).join('')}</div>`:''}<small>${m.role==='staff'?'Администратор · демо':m.role==='user'?'Вы':m.mode==='ai'?'ИИ · Groq':'Справочник по прайсу'}</small>${m.notice?`<div class="support-notice">${esc(m.notice)}</div>`:''}</div>`).join('')}${s.busy?'<div class="support-typing" role="status">Подбираем бережный ответ <span>···</span></div>':''}</div>${!t.messages.length?'<div class="support-quick"><button data-support-query="Сколько стоит комплекс для мальтипу?">Цена для мальтипу</button><button data-support-query="Есть ли доставка?">Доставка</button><button data-support-query="Как вы работаете?">Часы работы</button></div>':''}<form id="support-form"><textarea name="message" rows="2" maxlength="1600" required placeholder="Например: мальтипу, 4 кг, нужен комплекс" aria-label="Сообщение поддержке" ${s.busy?'disabled':''}></textarea><button type="submit" aria-label="Отправить" ${s.busy?'disabled':''}>${icon('arrow')}</button></form><footer><button id="support-book">Выбрать окошко ↗</button><button id="support-human">${t.mode==='human'?'Продолжить с помощником':'Связаться с администратором'}</button></footer><div class="support-knowledge-date">Прайс от 07.11.2026 · ${s.configured?'ответы ИИ проверяются по справочнику':'внешний ИИ не подключён; расходов нет'}</div></section>`:''}`;
 document.querySelector('#support-toggle').onclick=()=>{s.open=!s.open;draw();if(s.open)document.querySelector('#support-form textarea')?.focus()};document.querySelector('#support-close')?.addEventListener('click',()=>{s.open=false;draw()});document.querySelector('#support-book')?.addEventListener('click',()=>{s.open=false;draw();startBooking()});document.querySelector('#support-human')?.addEventListener('click',()=>{if(t.mode==='human'){const threads=read(),active=threads.find(x=>x.id===t.id);active.mode='auto';active.status='open';save(threads);draw()}else handoff()});
 document.querySelector('#support-form')?.addEventListener('submit',e=>{e.preventDefault();const text=e.target.elements.message.value.trim();if(text)send(text)});
 document.querySelector('#support-form textarea')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();document.querySelector('#support-form').requestSubmit()}});
 document.querySelectorAll('[data-support-query]').forEach(btn=>btn.onclick=()=>send(btn.dataset.supportQuery));const list=document.querySelector('#support-messages');if(list)list.scrollTop=list.scrollHeight;
 }
 async function send(text){if(s.busy||!text.trim())return;const before=thread(),history=historyForSupport(before.messages);append('user',text.slice(0,1600));if(before.mode==='human'){draw();return}s.busy=true;draw();let reply;try{if(s.available){const r=await fetch('/api/support/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text.slice(0,1600),history,profile:before.profile||null}),signal:AbortSignal.timeout(24000)});if(r.ok)reply=await r.json()}if(!reply){const p=buildSupportPlan(text,history,before.profile||null);reply={...p,sources:p.sources.map(sourceCard)}}if(reply.profile){const threads=read(),active=threads.find(t=>t.id===before.id);active.profile=reply.profile;save(threads)}append('assistant',reply.answer,{sources:reply.sources,mode:reply.mode,notice:reply.notice,revision:reply.revision});if(reply.handoff&&config.mode==='demo')handoff();if(reply.handoff&&config.mode!=='demo')toast('Можно связаться с администратором кнопкой внизу чата')}catch{const p=buildSupportPlan(text,history,before.profile||null);append('assistant',p.answer,{mode:'reference',sources:p.sources.map(sourceCard),notice:'Сеть недоступна. Ответ из встроенного прайса.'})}finally{s.busy=false;draw()}}
 function handoff(){if(config.mode!=='demo'){append('assistant',`С администратором можно связаться по телефону ${salonFacts.phone}. Общая очередь поддержки ещё не подключена.`);draw();return}const current=thread();let threads=read(),t=threads.find(t=>t.id===current.id);t.mode='human';t.status='waiting';t.updated=new Date().toISOString();save(threads);append('assistant',`Обращение появилось в демонстрационной очереди команды. Здесь администратор может ответить вручную. Для связи со студией по телефону: ${salonFacts.phone}.`,{mode:'reference'});draw()}
 function inbox(){if(config.mode!=='demo')return '<div class="notice">Общая очередь клиентских диалогов требует серверного хранилища, авторизации и привязки обращений к клиентам. Здесь не показываются чужие локальные переписки.</div>';const ts=read().sort((a,b)=>(b.updated||b.created).localeCompare(a.updated||a.created));if(!s.selected||!ts.some(t=>t.id===s.selected))s.selected=ts[0]?.id;const t=ts.find(t=>t.id===s.selected);const name=t=>{const u=state.data.users?.find(u=>u.user_id===t.owner);return u?[u.name,u.surname].filter(Boolean).join(' '):'Клиент'};return `<div class="page-head"><div><div class="eyebrow">ВСЕГДА НА СВЯЗИ</div><h1>Поддержка с <em>заботой.</em></h1><p class="sub">Демо-диалоги из клиентского приложения в этом браузере.</p></div><span class="pill rose">${ts.filter(t=>t.status==='waiting').length} ждут человека</span></div><div class="support-inbox"><aside>${ts.map(t=>`<button data-thread="${t.id}" class="${t.id===s.selected?'selected':''}"><b>${esc(name(t))}</b><span class="pill ${t.status==='waiting'?'amber':'green'}">${t.status==='waiting'?'Ждёт ответа':t.mode==='human'?'Человек':'Помощник'}</span><p>${esc(t.messages.at(-1)?.text.slice(0,100)||'Новый диалог')}</p></button>`).join('')||'<p class="sub" style="padding:25px">Пока нет обращений.</p>'}</aside><section>${t?`<header><div><h3>${esc(name(t))}</h3><p>${t.mode==='human'?'Автоответы приостановлены':'Отвечает помощник'}</p></div><button class="secondary" id="support-resume">${t.mode==='human'?'Вернуть помощнику':'Взять диалог'}</button></header><div class="support-inbox-messages">${t.messages.map(m=>`<div class="support-message ${m.role==='user'?'user':m.role==='staff'?'staff':'assistant'}"><p>${esc(m.text)}</p><small>${m.role==='user'?'Клиент':m.role==='staff'?'Администратор':m.mode==='ai'?'ИИ':'Справочник'}</small></div>`).join('')||'<p class="sub">Диалог только начат.</p>'}</div><form id="staff-support-reply"><textarea name="reply" required maxlength="2000" placeholder="Ответить клиенту вручную…" aria-label="Ответ клиенту"></textarea><button class="primary" type="submit">Ответить ${icon('arrow')}</button></form><p class="local-caption">Ответ сохраняется в демо-диалоге. В Telegram и другим людям сообщения отсюда не отправляются.</p>`:'<div class="empty"><h3>Каждому вопросу — внимание.</h3><p>Откройте поддержку в клиентском кабинете и создайте пробное обращение.</p></div>'}</section></div>`}
 function bindInbox(){document.querySelectorAll('[data-thread]').forEach(btn=>btn.onclick=()=>{s.selected=btn.dataset.thread;renderApp()});document.querySelector('#support-resume')?.addEventListener('click',()=>{const ts=read(),t=ts.find(t=>t.id===s.selected);t.mode=t.mode==='human'?'auto':'human';t.status=t.mode==='auto'?'resolved':'waiting';save(ts);renderApp()});document.querySelector('#staff-support-reply')?.addEventListener('submit',e=>{e.preventDefault();const ts=read(),t=ts.find(t=>t.id===s.selected),text=e.target.elements.reply.value.trim();if(!text)return;t.mode='human';t.status='answered';t.messages.push({id:crypto.randomUUID(),role:'staff',text,at:new Date().toISOString()});t.updated=new Date().toISOString();save(ts);renderApp();toast('Ответ появился в демо-кабинете клиента')})}
 window.addEventListener('storage',e=>{if(e.key===KEY){if(state.portal==='client'&&s.open)draw();else if(state.page==='support')renderApp()}});
 return {mount,inbox,bindInbox};
}

export function historyForSupport(messages){const result=[];let size=0;for(const m of messages.filter(m=>m.role==='user'||m.role==='assistant'&&m.revision===SUPPORT_REVISION).slice(-12).reverse()){const h={role:m.role,content:m.text.slice(0,m.role==='user'?600:500)};const bytes=new TextEncoder().encode(JSON.stringify(h)).length;if(size+bytes>10000)break;result.unshift(h);size+=bytes}return result}
